package finance.data.serializer;

import finance.feedback.*;
import finance.gameplay.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;

import java.util.*;

public final class WorldFeedbackDataSerializer {
    public static final String ROOT="WorldEconomyFeedback";
    private WorldFeedbackDataSerializer(){}
    public static void save(CompoundTag root){CompoundTag data=new CompoundTag();data.putInt("Version",1);ListTag cooldowns=new ListTag();WorldEconomyFeedbackService.cooldowns().forEach((key,day)->{CompoundTag tag=new CompoundTag();tag.putString("Key",key);tag.putLong("Day",day);cooldowns.add(tag);});data.put("Cooldowns",cooldowns);ListTag pending=new ListTag();WorldEconomyFeedbackService.pending().forEach((player,items)->{CompoundTag tag=new CompoundTag();tag.putUUID("Player",player);ListTag list=new ListTag();for(FeedbackNotification item:items){CompoundTag n=new CompoundTag();n.putLong("Day",item.worldDay());n.putString("Severity",item.severity().name());n.putString("Translation",item.translationKey());ListTag args=new ListTag();for(String arg:item.arguments())args.add(StringTag.valueOf(arg));n.put("Args",args);list.add(n);}tag.put("Items",list);pending.add(tag);});data.put("Pending",pending);ListTag terminals=new ListTag();for(WorldTerminalRegistry.TerminalRecord record:WorldTerminalRegistry.all()){CompoundTag tag=new CompoundTag();tag.putString("Dimension",record.dimensionId());tag.putLong("Pos",record.position().asLong());tag.putString("Type",record.type().name());terminals.add(tag);}data.put("Terminals",terminals);root.put(ROOT,data);}
    public static void load(CompoundTag root){WorldEconomyFeedbackService.clearDirect();WorldTerminalRegistry.clearDirect();if(!root.contains(ROOT,Tag.TAG_COMPOUND))return;CompoundTag data=root.getCompound(ROOT);ListTag cooldowns=data.getList("Cooldowns",Tag.TAG_COMPOUND);for(int i=Math.max(0,cooldowns.size()-WorldEconomyFeedbackService.MAX_COOLDOWNS);i<cooldowns.size();i++){CompoundTag tag=cooldowns.getCompound(i);WorldEconomyFeedbackService.restoreCooldown(tag.getString("Key"),tag.getLong("Day"));}ListTag pending=data.getList("Pending",Tag.TAG_COMPOUND);for(int i=0;i<Math.min(WorldEconomyFeedbackService.MAX_PENDING_PLAYERS,pending.size());i++){try{CompoundTag tag=pending.getCompound(i);UUID player=NbtDataSupport.readUuidOrNull(tag,"Player");if(player==null)continue;List<FeedbackNotification> items=new ArrayList<>();ListTag list=tag.getList("Items",Tag.TAG_COMPOUND);for(int j=0;j<Math.min(WorldEconomyFeedbackService.MAX_PENDING_PER_PLAYER,list.size());j++){CompoundTag n=list.getCompound(j);FeedbackSeverity severity=NbtDataSupport.safeEnum(FeedbackSeverity.class,n.getString("Severity"),null);if(severity==null)continue;ListTag args=n.getList("Args",Tag.TAG_STRING);List<String> values=new ArrayList<>();for(int a=0;a<Math.min(WorldEconomyEvent.MAX_ARGUMENTS,args.size());a++)values.add(args.getString(a));items.add(new FeedbackNotification(n.getLong("Day"),severity,n.getString("Translation"),values));}WorldEconomyFeedbackService.restorePending(player,items);}catch(RuntimeException ignored){}}ListTag terminals=data.getList("Terminals",Tag.TAG_COMPOUND);for(int i=0;i<Math.min(WorldTerminalRegistry.MAX_TERMINALS,terminals.size());i++){try{CompoundTag tag=terminals.getCompound(i);String dimension=tag.getString("Dimension");FinanceTerminalType type=NbtDataSupport.safeEnum(FinanceTerminalType.class,tag.getString("Type"),null);if(type!=null&&ResourceLocation.tryParse(dimension)!=null)WorldTerminalRegistry.restore(new WorldTerminalRegistry.TerminalRecord(dimension,BlockPos.of(tag.getLong("Pos")),type));}catch(RuntimeException ignored){}}}
}
